  watch(() => [state.etapa.value, state.imovel.value.titulo], () => {
    const editor = descricaoEditor.value;
    if (!editor || (state.isEdit && !state.imovel.value.titulo)) return;
    editor.innerHTML = state.imovel.value.descricao || '';
  }, { immediate: true });
  return { ...state, formatarPreco, descricaoEditor };
